using System;using System.Collections.Generic;using System.Web.Script.Serialization;using TechScope.Desktop;
class DesktopManagerSummaryTests {
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);}
 static Dictionary<string,object> Fixture(){var j=new JavaScriptSerializer();return j.Deserialize<Dictionary<string,object>>("{\"schema\":1,\"accountId\":\"paired-capital50k-20261021-pm-a\",\"modelHash\":\"f0b16e0c0922e3ae051015c3f73a66135c2a0b4ed478b5c0a3bfe6471ad0b0dd\",\"budget\":50000,\"at\":\"2026-10-26T05:27:50Z\",\"exportedAt\":\"2026-10-26T05:27:55Z\",\"summary\":{\"available\":true,\"fresh\":true,\"id\":\"paired-capital50k-20261021-pm-a\",\"budget\":50000,\"at\":\"2026-10-26T05:27:50Z\",\"model\":{\"hash\":\"f0b16e0c0922e3ae051015c3f73a66135c2a0b4ed478b5c0a3bfe6471ad0b0dd\",\"horizon\":20,\"cutoff\":\"2024-12-31\"},\"equity\":49000,\"cash\":38000,\"marketValue\":11000,\"exposure\":0.22448979591836735,\"risk\":null,\"action\":{\"code\":\"hold\",\"label\":\"hold\",\"reason\":\"frozen\"},\"holdings\":[],\"investmentReady\":false,\"realOrdersAllowed\":false,\"verifiedProfitProbability\":null}}");}
 static int Main(){try{var j=new JavaScriptSerializer();var now=DateTimeOffset.Parse("2026-10-26T05:28:00Z");var p=Fixture();Check(DesktopManagerSummary.Validate(j.Serialize(p),now),"valid fixed summary");foreach(string key in new[]{"accountId","modelHash","at","exportedAt"}){p=Fixture();p[key]="wrong";Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"bad "+key);}p=Fixture();p["at"]="2026-10-26T05:20:00Z";Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"stale account clock");p=Fixture();p["budget"]=10000;Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"old 10k rejected");Check(typeof(IDesktopBridge).GetMethod("ReadManagerSummary").GetParameters().Length==0,"bridge has no path argument");p=Fixture();var summary=(Dictionary<string,object>)p["summary"];summary["realOrdersAllowed"]=true;Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"nested real orders denied");p=Fixture();summary=(Dictionary<string,object>)p["summary"];summary["id"]="foreign";Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"nested identity denied");p=Fixture();summary=(Dictionary<string,object>)p["summary"];summary["fresh"]=false;Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"paused view cannot hold");((Dictionary<string,object>)summary["action"])["code"]="wait_verification";Check(DesktopManagerSummary.Validate(j.Serialize(p),now),"paused view waits");p=Fixture();p["at"]="2026-10-26T05:28:01Z";Check(!DesktopManagerSummary.Validate(j.Serialize(p),now),"future account clock denied");Check(!DesktopManagerSummary.Validate(new string(' ',65537),now),"oversize denied");Console.WriteLine("PASS 14 native manager-summary boundary checks");return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
